/* ---------- Friction hydroalcoolique ---------- */
/* Deux mains schématiques : la droite est le miroir de la gauche. pose : écart, rotation, chevauchement. */
function aTwoHands(x,y,o={}){const L=vG(-(o.gap==null?30:o.gap),o.dy||0,o.rl||0,o.s||1,aPalm(0,0,0,{glove:o.glove})),R=vG(o.gap==null?30:o.gap,-(o.dy||0),0,1,`<g transform="scale(-1 1) rotate(${v1(o.rr||0)})">${aPalm(0,0,0,{glove:o.glove,s:o.s||1})}</g>`);
 return vG(x,y,o.r||0,1,o.rightBack?R+L:L+R);}
const fhaStep=(c,o)=>sc(o.d||3,c,t=>{const m=vO(t,.55,1);return vBg()+aTwoHands(210,170,o.pose(m,t))+(o.extra?o.extra(t):"")+vTag(400,64,o.tag)+vT(400,100,o.n,{s:28,w:800,f:VC.acc});});
VV("friction-hydroalcoolique","Friction hydroalcoolique",[
 sc(3.4,"Remplir le creux de la main de produit",t=>{const pr=vS(t,.4,.9)-vS(t,1.4,1.9);return vBg()+aPalm(200,200,-10,{s:1.2})+vG(220,vL(46,58,pr),0,1,`<rect x="-24" y="10" width="48" height="76" rx="10" fill="#EAF4FB" stroke="#8FBCE0" stroke-width="1.4"/><rect x="-6" y="-10" width="12" height="22" fill="#D9E2E8" stroke="#9AA6B1"/><rect x="-26" y="-18" width="40" height="10" rx="3" fill="#B8C2CB" stroke="#7B8792"/>${vT(0,52,"SHA",{s:10,w:800,f:"#3E7FAE"})}`)+[0,1,2].map(i=>{const ph=vC((t-1-i*.35)/.6);return ph>0&&ph<1?`<ellipse cx="208" cy="${v1(150+ph*40)}" rx="4" ry="5" fill="#BFE0F5" stroke="#8FBCE0"/>`:"";}).join("")+vOp(vS(t,2.2,2.6),`<ellipse cx="196" cy="186" rx="22" ry="10" fill="#BFE0F5" opacity=".8"/>`+vTag(360,210,"Remplir le creux de la main"));}),
 fhaStep("Frotter paume contre paume",{n:"2",tag:"Paume contre paume",pose:m=>({gap:16,dy:m*14})}),
 fhaStep("Paume sur le dos de l'autre main, doigts entrelacés, puis inverser",{n:"3",tag:"Paume sur le dos",pose:(m,t)=>({gap:6+m*6,dy:4,rightBack:t>1.5,rr:8})}),
 fhaStep("Paume contre paume, doigts entrelacés",{n:"4",tag:"Doigts entrelacés",pose:m=>({gap:4,dy:m*8,rr:-6})}),
 fhaStep("Dos des doigts dans la paume opposée, doigts emboîtés",{n:"5",tag:"Doigts emboîtés",pose:m=>({gap:12,dy:20+m*6,r:90*0+m*4,rl:-80,rr:-80})}),
 fhaStep("Pouce dans la paume opposée en rotation, puis inverser",{n:"6",tag:"Les pouces",pose:m=>({gap:18,dy:0,rr:m*30})}),
 fhaStep("Bout des doigts et ongles en rotation dans la paume opposée",{n:"7",tag:"Bout des doigts",pose:m=>({gap:10,dy:-30,rl:m*20,rr:150})}),
 sc(4,"Frotter les poignets, jusqu'à ce que les mains soient sèches : 20 à 30 secondes",t=>{const m=vO(t,.6,1);return vBg()+aTwoHands(210,150,{gap:22,dy:40+m*8,rr:60})+vTimer(400,120,vC(t/3.6),"30 s",{r:26,s:13})+vOp(vS(t,2.8,3.4),vTag(400,180,"Mains sèches ✓",{bg:VC.ok,f:"#fff"}));})
],{poster:1});

