 sc(3.4,"Faute d'asepsie : changer de gants",t=>vBg()+aPalm(200,170,0,{glove:1,s:1.1})+`<rect x="236" y="96" width="70" height="16" rx="4" fill="#3E474F" transform="rotate(-20 270 104)"/>`+vNo(310,80,vS(t,.4,1),16)+vOp(vS(t,1.4,1.8),vTag(330,230,"On change de gants",{bg:VC.warn,f:"#fff"})))
