 sc(5.4,"Gonfler puis dégonfler lentement en écoutant l'artère (ou mesure automatique)",t=>{const p=vK(t,[[0,0],[1.4,170],[4.6,40],[5.4,0]]);return vBg()+aArm({})+aCuff(0,170,{inf:p/170})+aGauge(380,90,p,{s:1.05})+vG(112,166,0,1,`<circle r="11" fill="#D9DEE3" stroke="#6F7B86" stroke-width="2"/><path d="M0 -11C0 -40 30 -60 60 -70" stroke="#3E474F" stroke-width="3" fill="none"/>`)+(p<128&&p>76&&t>1.4?`<path d="M150 120q8 -8 0 -16M160 126q14 -14 0 -28" stroke="${VC.acc}" stroke-width="2" fill="none"/>`:"")+vOp(vC((t-2.4)*3)*(p<128?1:0),vTag(380,160,"1er bruit : PAS 128"))+vOp(t>3.6?1:0,vTag(380,186,"Disparition : PAD 76"));}),
 sc(3,"Lire la pression systolique, diastolique et la fréquence cardiaque",t=>vBg()+vPanel(140,70,200,120,`${vT(240,122,"128 / 76",{s:30,w:800})}${vT(240,148,"mmHg",{s:11,w:700,f:VC.sub})}${vT(240,174,"FC 72 /min",{s:13,w:800,f:VC.acc})}`)+vCheck(370,80,vS(t,.6,1.6),14)),
 sc(3.2,"À la première mesure, comparer les deux bras ; recontrôler une valeur anormale",t=>vBg()+aBust(240,170,{})+vOp(vS(t,.3,.8),vTag(140,110,"Bras droit 128/76"))+vOp(vS(t,1,1.5),vTag(340,110,"Bras gauche 126/74"))+vCheck(240,60,vS(t,1.8,2.6),14))
