/* ---------- Gaz du sang artériel ---------- */
function aHandUp(x,y,o={}){const pale=vC(o.pale||0),f=pale?`rgb(${v1(vL(235,246,pale))},${v1(vL(194,232,pale))},${v1(vL(164,220,pale))})`:"url(#vd-skin)";
 return vG(x,y,o.r||0,o.s||1,`<path d="M-40 140V40C-40 20 -36 0 -30 -20C-30 -46 -14 -46 -14 -22V-60C-14 -74 2 -74 2 -60V-66C2 -80 18 -80 18 -66V-58C18 -72 34 -72 34 -56V-10C40 -24 56 -22 54 -6C50 14 44 26 40 40V140Z" fill="${f}" stroke="${VC.skinL}" stroke-width="1.5"/><path d="M-30 90H40" stroke="${VC.skinL}" opacity=".5"/>`);}
VV("gaz-du-sang","Gaz du sang artériel",[
 sc(3.4,"Vérifier la prescription et noter le débit d'oxygène (ou air ambiant) depuis au moins 20 minutes",t=>vBg()+vDoc(60,60,{title:"Avant la ponction",lines:["Prescription","O₂ : 2 L/min depuis 20 min","Anticoagulant ?"],u:vS(t,.2,2.6),w:210})+vTimer(380,150,vC(t/3),"20 min",{r:28,s:11})),
 sc(5,"Réaliser le test d'Allen",t=>{const c=vS(t,.2,.8),pale=vS(t,.8,2)*(1-vS(t,3,3.8));return vBg()+aHandUp(240,150,{pale,s:1.05})+vG(vL(150,206,c),262,-90,.75,aHand(0,0,0,{}))+vG(vL(330,274,c),262,-90,.75,aHand(0,0,0,{}))+vOp(vS(t,.8,1.2),vTag(390,60,"1 · Comprimer les 2 artères"))+vOp(vS(t,2,2.4),vTag(390,94,"2 · La main pâlit"))+vOp(vS(t,3,3.4),vTag(390,128,"3 · Relâcher la cubitale"))+vOp(vS(t,3.8,4.2),vTag(390,170,"Recoloration < 10 s ✓",{bg:VC.ok,f:"#fff"}));}),
 sc(3.4,"Repérer l'artère radiale par palpation, antisepsie",t=>vBg()+aArm({noVein:1})+`<path d="M250 186C290 186 310 184 334 182" stroke="#D9584F" stroke-width="4" opacity=".55" fill="none"/>`+[0,1,2].map(i=>{const ph=(t*1.2+i/3)%1;return `<circle cx="300" cy="184" r="${v1(6+ph*16)}" fill="none" stroke="#D9584F" opacity="${v1(1-ph)}"/>`;}).join("")+antisep(Math.max(0,t-1),300,184,{r:24})+vTag(300,236,"Pouls radial")),
 sc(5,"Piquer à 45°, biseau vers le haut, face au flux : le sang monte seul",t=>{const u=vS(t,.4,1.6),fill=t<1.8?.04:.04+vC((t-1.8)/2.6)*.5+Math.max(0,vO(t,.8,.03));return vBg()+aSkin({y:150,artery:30})+aSyringe(vL(330,236,u),vL(116,187,u),-45,{fill,nl:30,len:56,liq:"#C9372D"})+vOp(vS(t,1.8,2.2),vTag(380,60,"Remplissage pulsatile"))+`<path d="M120 237H180" stroke="#A3352E" stroke-width="2"/><path d="M172 233l8 4-8 4" fill="#A3352E"/>`+vT(150,252,"flux",{s:9,w:700,f:"#A3352E"});}),
 sc(3.6,"Retirer et comprimer au moins 5 minutes (plus sous anticoagulant)",t=>vBg()+aArm({noVein:1})+aGauze(300,182,0,{wet:"#E9B0A8"})+aHand(306,176,-70,{s:.85})+vTimer(400,70,vC(t/3.2),"5 min",{r:24,s:11})),
 sc(3.4,"Chasser immédiatement les bulles d'air, boucher, rouler la seringue",t=>{const m=vO(t,.5,10);return vBg()+aSyringe(140,150+m*.2,0,{fill:.5,nl:0,len:120,liq:"#C9372D"})+aPalm(220-m,100,180,{s:.8})+aPalm(220+m,206,0,{s:.8})+vTag(380,80,"Sans bulle, bouchée, roulée");}),
 sc(3,"Étiqueter et faire analyser sans délai (15 à 30 minutes)",t=>vBg()+vTimer(170,150,vC(t/2.6),"< 30 min",{r:32,s:11})+vDoc(250,80,{title:"Étiquette",lines:["Identité","Heure, FiO₂ ou débit O₂","Température"],u:vS(t,.2,2.4),w:180}))
],{poster:3});

/* ---------- Prélèvement nasopharyngé ---------- */
const swab=(x1,y1,x2,y2)=>`<path d="M${v1(x1)} ${v1(y1)}L${v1(x2)} ${v1(y2)}" stroke="#E9EDF0" stroke-width="3" stroke-linecap="round"/><path d="M${v1(x1)} ${v1(y1)}L${v1(x2)} ${v1(y2)}" stroke="#9AA6B1" stroke-width="1"/><ellipse cx="${v1(x1)}" cy="${v1(y1)}" rx="5" ry="3.4" fill="#FFFFFF" stroke="#C9C3B6"/>`;
VV("prelevement-nasopharynge","Prélèvement nasopharyngé",[
 sc(2.8,"Faire moucher le patient",t=>vBg()+aHead(250,170,{s:1.4,cut:false})+vG(vL(160,184,vS(t,.3,1)),126,0,1,`<rect x="-18" y="-16" width="36" height="32" rx="6" fill="#FFFFFF" stroke="#CFC8BA"/>`)+vTag(380,80,"Se moucher")),
 sc(4.4,"Introduire l'écouvillon horizontalement, le long du plancher de la narine",t=>{const u=vS(t,.4,3);return vBg()+aHead(250,170,{s:1.4,labels:1})+swab(vL(196,262,u),139,vL(130,196,u),139)+vOp(vS(t,.4,.8),`<path d="M200 128H316" stroke="${VC.acc}" stroke-dasharray="4 4"/>`+vT(260,120,"≈ distance narine → oreille",{s:9,w:700,f:VC.acc}))+vNo(160,80,vS(t,1.2,1.8),10)+vT(160,64,"pas vers le haut",{s:9,w:800,f:VC.warn});}),
 sc(3,"Tourner doucement quelques secondes",t=>vBg()+aHead(250,170,{s:1.4})+swab(262,139,196,139)+`<ellipse cx="262" cy="139" rx="9" ry="9" fill="none" stroke="${VC.acc}" stroke-width="2" stroke-dasharray="${v1(10+vO(t,.4,4))} 4"/>`+vTimer(400,70,vC(t/2.6),"5 s",{r:20,s:10})),
 sc(3.4,"Retirer et placer l'écouvillon dans le milieu de transport",t=>{const u=vS(t,.3,2);return vBg()+aTube(330,110,{cap:"#C0563B",fill:.25,liq:"#F4E27A",h:110,s:1.1})+swab(vL(196,330,u),vL(139,216,u),vL(130,330,u),vL(139,96,u));}),
 sc(2.8,"Étiqueter et acheminer",t=>vBg()+aTube(180,90,{cap:"#C0563B",fill:.25,liq:"#F4E27A",h:110,label:1,s:1.2})+vDoc(250,80,{title:"Étiquette",lines:["Identité","Date et heure"],u:vS(t,.2,2),w:180}))
],{poster:1});

/* ---------- Pansement simple ---------- */
function aWound(x,y,o={}){const cl=vC(o.clean||0);return `<ellipse cx="${x}" cy="${y}" rx="${o.rx||170}" ry="${o.ry||92}" fill="url(#vd-skin)" stroke="${VC.skinL}" stroke-width="1.4"/><ellipse cx="${x}" cy="${y}" rx="64" ry="20" fill="#E6928A" opacity="${v1(.35*(1-cl*.5))}"/><path d="M${x-56} ${y}C${x-20} ${y-6} ${x+20} ${y+6} ${x+56} ${y}" stroke="#B5524A" stroke-width="6" stroke-linecap="round" fill="none"/>${o.exu?`<ellipse cx="${x+10}" cy="${y+6}" rx="${v1(22*(1-cl))}" ry="${v1(8*(1-cl))}" fill="#E8D27A" opacity=".8"/>`:""}`;}
const sterSet=(o={})=>vPanel(70,150,340,110,`<rect x="86" y="166" width="308" height="80" rx="6" fill="#D8ECF8"/>${aGauze(130,206,0,{})}${aGauze(170,206,0,{})}${aForceps(220,206,0,{s:.8})}<ellipse cx="350" cy="206" rx="26" ry="18" fill="#EAF4FB" stroke="#8FBCE0"/>${vT(350,210,"NaCl",{s:9,w:800,f:"#3E7FAE"})}`,{r:10});
VV("pansement-simple","Pansement simple",[
 sc(3.6,"Friction, gants non stériles, retirer l'ancien pansement et l'éliminer avec les gants",t=>{const p=vS(t,.4,2.4);return vBg()+aWound(240,150,{exu:1})+`<rect x="${v1(vL(150,300,p))}" y="${v1(vL(112,60,p))}" width="180" height="76" rx="8" fill="#FBFAF6" stroke="#CFC8BA" opacity="${v1(1-p*.7)}"/>`+aHand(vL(330,420,p),vL(118,70,p),200,{s:.8});}),
 sc(3.2,"Observer la plaie : aspect, écoulement, berges, rougeur",t=>vBg()+aWound(240,150,{exu:1})+[["Aspect",100,60],["Écoulement",380,60],["Berges",100,240],["Rougeur",380,240]].map(([l,x,y],i)=>vOp(vS(t,.3+i*.5,.7+i*.5),vTag(x,y,l))).join("")),
 sc(3.2,"Friction, ouvrir le set de façon aseptique",t=>vBg()+sterSet()+vOp(1-vS(t,.4,1.6),`<rect x="70" y="150" width="340" height="110" rx="10" fill="#EAF2F8" stroke="#9AA6B1"/>`)+vTag(240,110,"Set stérile ouvert sans toucher l'intérieur")),
 sc(5,"Nettoyer au sérum physiologique du plus propre au plus sale, une compresse par passage",t=>{const k=Math.min(2,Math.floor(t/1.6)),lt=(t-k*1.6)/1.4,P=[[[184,150],[296,150]],[[180,128],[300,128]],[[180,172],[300,172]]],[a,b]=P[k],u=vS(lt,0,1);
  return vBg()+aWound(240,150,{exu:1,clean:vC(t/4.4)})+aGauze(vL(a[0],b[0],u),vL(a[1],b[1],u),0,{wet:"#BFE0F5",size:26})+vT(240,260,`Passage ${k+1} · compresse neuve`,{s:11,w:800,f:VC.acc})+vTag(240,40,"Du centre de la plaie vers l'extérieur");}),
 sc(3,"Sécher par tamponnement",t=>vBg()+aWound(240,150,{clean:1})+aGauze(vL(200,280,vS(t,.2,2.6)),150-Math.abs(vO(t,.5,8)),0,{size:30})),
 sc(3,"Appliquer l'antiseptique si prescrit, laisser sécher",t=>vBg()+aWound(240,150,{clean:1})+antisep(t,240,150,{r:70,t1:1.8})),
 sc(3.4,"Appliquer le pansement en débordant de la plaie, dater",t=>vBg()+aWound(240,150,{clean:1})+`<rect x="130" y="${v1(vL(20,108,vS(t,.3,1.6)))}" width="220" height="84" rx="10" fill="#FBFAF6" stroke="#CFC8BA"/><rect x="160" y="${v1(vL(32,120,vS(t,.3,1.6)))}" width="160" height="60" rx="6" fill="#F2EEE4"/>`+vOp(vS(t,1.8,2.2),vTag(240,90,"07/11 · 14 h 30",{bg:"#FFF6C9"}))),
 sTrace("Éliminer les déchets, friction, tracer",["Aspect de la plaie","Produits utilisés","Prochaine réfection"])
],{poster:3});

/* ---------- Ablation de fils et d'agrafes ---------- */
function aStapler(x,y,r,o={}){const sq=vC(o.sq||0);return vG(x,y,r,o.s||1,`<path d="M0 0L70 ${v1(-14+sq*6)}L74 ${v1(-8+sq*6)}L6 4Z" fill="url(#vd-metal)" stroke="#6F7B86"/><path d="M0 0L70 ${v1(14-sq*6)}L74 ${v1(8-sq*6)}L6 -4Z" fill="url(#vd-metal)" stroke="#6F7B86"/><path d="M-6 -3H4V3H-6Z" fill="#6F7B86"/>`);}
VV("ablation-fils","Ablation de fils et d'agrafes",[
 sc(3.2,"Vérifier la prescription : date, ablation totale ou un point sur deux",t=>vBg()+vDoc(120,60,{title:"Prescription",lines:["Ablation à J10","Un point sur deux d'abord","Puis ablation totale"],u:vS(t,.2,2.4),w:240})),
 sc(3.2,"Observer la cicatrice : désunie ou infectée, on ne retire pas",t=>vBg()+`<ellipse cx="240" cy="150" rx="190" ry="100" fill="url(#vd-skin)" stroke="${VC.skinL}"/>`+aScar(240,150,{n:6})+vOp(vS(t,.4,.8),vTag(110,60,"Berges fermées ?"))+vOp(vS(t,1,1.4),vTag(370,60,"Rougeur, écoulement ?"))+vCheck(240,250,vS(t,1.8,2.6),14)),
 sc(3,"Antisepsie de la cicatrice",t=>vBg()+`<ellipse cx="240" cy="150" rx="190" ry="100" fill="url(#vd-skin)" stroke="${VC.skinL}"/>`+aScar(240,150,{n:6})+antisep(t,240,150,{r:80,t1:2})),
 sc(5.2,"Fils : soulever le nœud, couper sous le nœud au ras de la peau, tirer",t=>{const lift=vS(t,.3,1.2),cut=vS(t,1.4,2.2),pull=vS(t,2.6,3.8),sx=240-110+220/7*2;return vBg()+`<ellipse cx="240" cy="150" rx="190" ry="100" fill="url(#vd-skin)" stroke="${VC.skinL}"/>`+aScar(240,150,{n:6,gone:[0,pull]})+aForceps(sx+4,vL(110,132,lift)-pull*20,-150,{s:.9,open:1-lift*.8})+vOp(vS(t,1,1.4)*(1-vS(t,2.4,2.8)),aScissors(sx+8,160,160,{s:.8,cut}))+vOp(vS(t,1.4,1.8),vTag(380,70,"Couper sous le nœud"))+vOp(vS(t,2.6,3),vTag(240,272,"Le fil extérieur ne traverse pas la peau"));}),
 sc(4.4,"Agrafes : glisser l'ôte-agrafes sous l'agrafe, serrer, retirer verticalement",t=>{const sq=vS(t,1,1.8),up=vS(t,2.2,3.4),sx=240-110+220/7*3;return vBg()+`<ellipse cx="240" cy="150" rx="190" ry="100" fill="url(#vd-skin)" stroke="${VC.skinL}"/>`+aScar(240,150,{n:6,staples:1,gone:[0,0,up]})+aStapler(sx,vL(90,150,vS(t,.2,.9))-up*26,-90,{sq,s:.9})+vOp(sq,vTag(380,80,"Serrer : l'agrafe se déforme"))+vOp(up,vTag(380,114,"Retirer verticalement"));}),
 sc(3.6,"Commencer souvent par un point sur deux, vérifier la tenue, puis terminer",t=>vBg()+`<ellipse cx="240" cy="150" rx="190" ry="100" fill="url(#vd-skin)" stroke="${VC.skinL}"/>`+aScar(240,150,{n:6,gone:[0,vS(t,.2,.8),0,vS(t,.8,1.4),0,vS(t,1.4,2)]})+vOp(vS(t,2.2,2.6),vTag(240,250,"Cicatrice tenue : on retire le reste"))),
 sc(3,"Antisepsie, bandelettes adhésives si besoin, pansement sec si nécessaire",t=>vBg()+`<ellipse cx="240" cy="150" rx="190" ry="100" fill="url(#vd-skin)" stroke="${VC.skinL}"/>`+aScar(240,150,{n:6,gone:[1,1,1,1,1,1]})+[0,1,2,3,4].map(i=>vOp(vS(t,.3+i*.3,.6+i*.3),`<rect x="${150+i*44}" y="134" width="14" height="32" rx="2" fill="#FBFAF6" stroke="#CFC8BA"/>`)).join(""))
],{poster:3});

/* ---------- Oxygène, aérosol, inhalateur ---------- */
function aFlowmeter(x,y,val,o={}){const max=o.max||15,yb=v1(70-vC(val/max)*120);return vG(x,y,0,o.s||1,`<g filter="url(#vd-sh)"><rect x="-18" y="-62" width="36" height="150" rx="10" fill="#EEF1F4" stroke="#9AA6B1" stroke-width="1.3"/></g><rect x="-8" y="-54" width="16" height="130" rx="6" fill="#FFFFFF" stroke="#B9C2CA"/>${[0,2,4,6,8,10,12,15].map(n=>`<path d="M-8 ${v1(70-n/max*120)}h5" stroke="#5F6B72"/>${vT(14,v1(70-n/max*120)+3,n,{s:6.5,w:700,f:VC.sub,a:"start"})}`).join("")}<circle cx="0" cy="${yb}" r="6" fill="#2C7451"/><rect x="-10" y="90" width="20" height="14" rx="3" fill="#2C7451"/>${vT(0,-70,o.label||"O₂ L/min",{s:8,w:800,f:"#2C7451"})}`);}
const nCannula=`<path d="M-36 -24C-30 -18 -10 -14 10 -18C34 -22 44 -46 52 -40C62 -32 60 -10 50 4C40 20 20 30 0 34" fill="none" stroke="#9FD3C0" stroke-width="3.4" stroke-linecap="round"/><path d="M-38 -26l-6 -3M-34 -27l-5 -5" stroke="#9FD3C0" stroke-width="3" stroke-linecap="round"/>`;
const hcMask=(inf)=>`<path d="M-56 -46C-44 -56 -26 -50 -18 -36L-14 14C-20 24 -40 26 -56 18Z" fill="#E6F3EE" fill-opacity=".75" stroke="#7CBCA4" stroke-width="1.6"/><path d="M-52 22V34" stroke="#7CBCA4" stroke-width="3"/><ellipse cx="-50" cy="${v1(52+inf*4)}" rx="${v1(12+inf*10)}" ry="${v1(10+inf*12)}" fill="#D7EFE6" stroke="#7CBCA4" stroke-width="1.4"/>`;
