/* ---------- Sonde urinaire ---------- */
function foley(tip,bal,urine){const y=vL(200,-36,tip),inB=y<44;return `<path d="M0 220V${v1(y)}" stroke="#E6C08A" stroke-width="6" stroke-linecap="round"/>${inB&&urine?`<path d="M0 220V${v1(y+4)}" stroke="#F4E27A" stroke-width="2.4" stroke-dasharray="${v1(220-y)} 400" stroke-dashoffset="${v1((220-y)*(1-urine))}"/>`:""}${bal>0?`<ellipse cx="0" cy="${v1(y+8)}" rx="${v1(4+bal*10)}" ry="${v1(3+bal*8)}" fill="#F1D9AE" stroke="#C9A06A"/>`:""}`;}
const urSet=(t)=>[["Toilette intime",0],["Friction",1],["Set stérile",2],["Gants stériles",3],["Champ",4]].map(([l,i])=>vOp(vS(t,.2+i*.5,.5+i*.5),vTag(240,46+i*44,`${i+1} · ${l}`))).join("");
