/* ---------- Contrôle ultime prétransfusionnel ---------- */
const cgr=(x,y,o={})=>aBag(x,y,Object.assign({liq:"#A3261F",level:.8,label:"CGR",vol:o.grp||"A +"},o));
function aCardABO(x,y,o={}){const ag=vC(o.ag||0),wells=[["Anti-A",1],["Anti-B",0]];
 const w=(cx,cy,pos)=>`<circle cx="${cx}" cy="${cy}" r="20" fill="#F3E9E6" stroke="#C9C3B6"/>${ag>0?(pos?[...Array(9)].map((_,i)=>`<circle cx="${v1(cx+Math.cos(i*2.4)*(i%3)*5)}" cy="${v1(cy+Math.sin(i*2.4)*(i%3)*5)}" r="${v1(2.6*ag+1)}" fill="#8E1F18"/>`).join(""):`<circle cx="${cx}" cy="${cy}" r="${v1(16*ag)}" fill="#C9372D" opacity=".75"/>`):""}`;
 return vPanel(x,y,240,150,`${vT(x+120,y+20,"Carte de contrôle ABO",{s:11,w:800})}${vT(x+30,y+64,"Patient",{s:9,w:800,a:"start"})}${vT(x+30,y+118,"Poche",{s:9,w:800,a:"start"})}${wells.map(([l,pos],i)=>vT(x+130+i*60,y+38,l,{s:8.5,w:700,f:VC.sub})+w(x+130+i*60,y+62,pos)+w(x+130+i*60,y+116,pos)).join("")}`,{r:12});}
